-- IPASS PostgreSQL schema draft
-- UUID values are generated by the application. Apply as a new database schema.
-- Review auth, roster-import, attempt-selection, and grading policies before production use.

BEGIN;

CREATE TYPE account_status AS ENUM ('active', 'suspended', 'pending');
CREATE TYPE problem_status AS ENUM ('draft', 'published', 'archived');
CREATE TYPE library_policy AS ENUM ('none', 'basic_only');
CREATE TYPE test_case_visibility AS ENUM ('public', 'hidden');
CREATE TYPE exam_status AS ENUM (
    'draft', 'scheduled', 'open', 'closed', 'grading', 'published', 'archived'
);
CREATE TYPE participant_status AS ENUM ('eligible', 'withdrawn');
CREATE TYPE submission_status AS ENUM ('queued', 'running', 'graded', 'error');
CREATE TYPE test_verdict AS ENUM ('AC', 'WA', 'RE', 'CE', 'TLE', 'MLE', 'SE');

CREATE TABLE app_users (
    id              uuid PRIMARY KEY,
    student_no      text,
    email           text NOT NULL,
    email_verified_at timestamptz,
    google_sub      text UNIQUE,
    full_name       text NOT NULL,
    status          account_status NOT NULL DEFAULT 'pending',
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    last_login_at   timestamptz,
    CONSTRAINT app_users_student_no_nonempty CHECK (student_no IS NULL OR length(trim(student_no)) > 0),
    CONSTRAINT app_users_email_nonempty CHECK (length(trim(email)) > 3)
);

CREATE UNIQUE INDEX app_users_email_lower_uq ON app_users (lower(email));
CREATE UNIQUE INDEX app_users_student_no_uq ON app_users (student_no) WHERE student_no IS NOT NULL;

CREATE TABLE roles (
    name text PRIMARY KEY CHECK (name IN ('admin', 'teacher', 'student'))
);

CREATE TABLE user_roles (
    user_id       uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
    role_name     text NOT NULL REFERENCES roles(name),
    assigned_by   uuid REFERENCES app_users(id) ON DELETE SET NULL,
    assigned_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role_name)
);

CREATE TABLE courses (
    id            uuid PRIMARY KEY,
    course_code   text NOT NULL,
    title         text NOT NULL,
    description   text,
    created_by    uuid REFERENCES app_users(id) ON DELETE SET NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    UNIQUE (course_code)
);

CREATE TABLE course_sections (
    id              uuid PRIMARY KEY,
    course_id       uuid NOT NULL REFERENCES courses(id) ON DELETE RESTRICT,
    section_code    text NOT NULL,
    academic_year   smallint NOT NULL,
    semester        smallint NOT NULL CHECK (semester > 0),
    created_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (course_id, academic_year, semester, section_code)
);

CREATE TABLE section_teachers (
    section_id    uuid NOT NULL REFERENCES course_sections(id) ON DELETE CASCADE,
    teacher_id    uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    assigned_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (section_id, teacher_id)
);

CREATE TABLE enrollments (
    id            uuid PRIMARY KEY,
    section_id    uuid NOT NULL REFERENCES course_sections(id) ON DELETE CASCADE,
    student_id    uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'dropped')),
    joined_at     timestamptz NOT NULL DEFAULT now(),
    UNIQUE (section_id, student_id)
);

CREATE TABLE problems (
    id            uuid PRIMARY KEY,
    created_by    uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    title         text NOT NULL,
    category      text,
    status        problem_status NOT NULL DEFAULT 'draft',
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE problem_versions (
    id                    uuid PRIMARY KEY,
    problem_id            uuid NOT NULL REFERENCES problems(id) ON DELETE RESTRICT,
    version_no            integer NOT NULL CHECK (version_no > 0),
    statement             text NOT NULL,
    constraints_text      text,
    input_description    text,
    output_description   text,
    examples              jsonb NOT NULL DEFAULT '[]'::jsonb,
    library_policy        library_policy NOT NULL DEFAULT 'basic_only',
    semantic_threshold   numeric(5,2) NOT NULL DEFAULT 95.00
                              CHECK (semantic_threshold >= 0 AND semantic_threshold <= 100),
    time_limit_ms         integer CHECK (time_limit_ms IS NULL OR time_limit_ms > 0),
    memory_limit_mb       integer CHECK (memory_limit_mb IS NULL OR memory_limit_mb > 0),
    status                problem_status NOT NULL DEFAULT 'draft',
    created_at            timestamptz NOT NULL DEFAULT now(),
    UNIQUE (problem_id, version_no),
    UNIQUE (id, problem_id)
);

CREATE TABLE problem_version_languages (
    problem_version_id   uuid NOT NULL REFERENCES problem_versions(id) ON DELETE CASCADE,
    language             text NOT NULL,
    runtime_version      text NOT NULL,
    PRIMARY KEY (problem_version_id, language, runtime_version)
);

CREATE TABLE problem_allowed_libraries (
    problem_version_id   uuid NOT NULL REFERENCES problem_versions(id) ON DELETE CASCADE,
    library_name         text NOT NULL,
    PRIMARY KEY (problem_version_id, library_name)
);

CREATE TABLE test_cases (
    id                  uuid PRIMARY KEY,
    problem_version_id  uuid NOT NULL REFERENCES problem_versions(id) ON DELETE RESTRICT,
    input_data          text NOT NULL,
    expected_output     text NOT NULL,
    visibility          test_case_visibility NOT NULL,
    required            boolean NOT NULL DEFAULT true,
    score_weight        numeric(8,2) NOT NULL DEFAULT 1.00 CHECK (score_weight >= 0),
    order_no            integer NOT NULL CHECK (order_no > 0),
    created_at          timestamptz NOT NULL DEFAULT now(),
    UNIQUE (problem_version_id, order_no),
    UNIQUE (problem_version_id, id)
);

CREATE TABLE exams (
    id                    uuid PRIMARY KEY,
    created_by            uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    title                 text NOT NULL,
    description           text,
    opens_at              timestamptz,
    closes_at             timestamptz,
    status                exam_status NOT NULL DEFAULT 'draft',
    allow_past_review     boolean NOT NULL DEFAULT false,
    leaderboard_enabled   boolean NOT NULL DEFAULT false,
    room_code_hash        text,
    results_published_at  timestamptz,
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT exams_valid_window CHECK (
        opens_at IS NULL OR closes_at IS NULL OR opens_at < closes_at
    )
);

CREATE TABLE exam_sections (
    exam_id       uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    section_id    uuid NOT NULL REFERENCES course_sections(id) ON DELETE RESTRICT,
    assigned_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (exam_id, section_id)
);

CREATE TABLE exam_participants (
    id                  uuid PRIMARY KEY,
    exam_id             uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    student_id          uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    source_section_id   uuid REFERENCES course_sections(id) ON DELETE SET NULL,
    status              participant_status NOT NULL DEFAULT 'eligible',
    added_by            uuid REFERENCES app_users(id) ON DELETE SET NULL,
    added_at            timestamptz NOT NULL DEFAULT now(),
    UNIQUE (exam_id, student_id),
    UNIQUE (exam_id, id)
);

CREATE TABLE exam_problems (
    id                  uuid PRIMARY KEY,
    exam_id             uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    problem_version_id  uuid NOT NULL REFERENCES problem_versions(id) ON DELETE RESTRICT,
    points              numeric(8,2) NOT NULL CHECK (points > 0),
    quality_points      numeric(8,2) NOT NULL DEFAULT 0 CHECK (quality_points >= 0 AND quality_points <= points),
    order_no            integer NOT NULL CHECK (order_no > 0),
    UNIQUE (exam_id, order_no),
    UNIQUE (exam_id, problem_version_id),
    UNIQUE (exam_id, id, problem_version_id)
);

CREATE TABLE submissions (
    id                    uuid PRIMARY KEY,
    exam_id               uuid NOT NULL,
    exam_participant_id   uuid NOT NULL,
    exam_problem_id       uuid NOT NULL,
    problem_version_id    uuid NOT NULL,
    attempt_no            integer NOT NULL CHECK (attempt_no > 0),
    source_code           text NOT NULL,
    language              text NOT NULL,
    runtime_version       text NOT NULL,
    status                submission_status NOT NULL DEFAULT 'queued',
    submitted_at          timestamptz NOT NULL DEFAULT now(),
    graded_at             timestamptz,
    UNIQUE (exam_participant_id, exam_problem_id, attempt_no),
    UNIQUE (id, problem_version_id),
    UNIQUE (id, exam_id, exam_participant_id, exam_problem_id),
    FOREIGN KEY (exam_id, exam_participant_id)
        REFERENCES exam_participants(exam_id, id) ON DELETE CASCADE,
    FOREIGN KEY (exam_id, exam_problem_id, problem_version_id)
        REFERENCES exam_problems(exam_id, id, problem_version_id) ON DELETE RESTRICT
);

CREATE TABLE submission_test_results (
    id                  uuid PRIMARY KEY,
    submission_id       uuid NOT NULL,
    problem_version_id  uuid NOT NULL,
    test_case_id        uuid NOT NULL,
    verdict             test_verdict NOT NULL,
    passed              boolean NOT NULL,
    exact_match         boolean NOT NULL,
    semantic_score      numeric(5,2) CHECK (semantic_score IS NULL OR (semantic_score >= 0 AND semantic_score <= 100)),
    stdout              text,
    stderr              text,
    exit_code           integer,
    runtime_ms          integer CHECK (runtime_ms IS NULL OR runtime_ms >= 0),
    memory_kb           integer CHECK (memory_kb IS NULL OR memory_kb >= 0),
    checked_at          timestamptz NOT NULL DEFAULT now(),
    UNIQUE (submission_id, test_case_id),
    FOREIGN KEY (submission_id, problem_version_id)
        REFERENCES submissions(id, problem_version_id) ON DELETE CASCADE,
    FOREIGN KEY (problem_version_id, test_case_id)
        REFERENCES test_cases(problem_version_id, id) ON DELETE RESTRICT
);

CREATE TABLE submission_assessments (
    submission_id       uuid PRIMARY KEY REFERENCES submissions(id) ON DELETE CASCADE,
    algorithm_pass      boolean,
    quality_score       numeric(8,2) CHECK (quality_score IS NULL OR quality_score >= 0),
    rubric_result       jsonb NOT NULL DEFAULT '{}'::jsonb,
    feedback            text,
    model_id            text,
    prompt_version      text,
    evaluated_at        timestamptz
);

CREATE TABLE exam_problem_results (
    exam_id                 uuid NOT NULL,
    exam_participant_id     uuid NOT NULL,
    exam_problem_id         uuid NOT NULL,
    selected_submission_id  uuid,
    testcase_score          numeric(8,2) NOT NULL DEFAULT 0 CHECK (testcase_score >= 0),
    quality_score           numeric(8,2) NOT NULL DEFAULT 0 CHECK (quality_score >= 0),
    final_score             numeric(8,2) NOT NULL DEFAULT 0 CHECK (final_score >= 0),
    is_pass                 boolean NOT NULL DEFAULT false,
    graded_at               timestamptz,
    PRIMARY KEY (exam_participant_id, exam_problem_id),
    FOREIGN KEY (exam_id, exam_participant_id)
        REFERENCES exam_participants(exam_id, id) ON DELETE CASCADE,
    FOREIGN KEY (exam_id, exam_problem_id)
        REFERENCES exam_problems(exam_id, id) ON DELETE CASCADE,
    FOREIGN KEY (selected_submission_id, exam_id, exam_participant_id, exam_problem_id)
        REFERENCES submissions(id, exam_id, exam_participant_id, exam_problem_id) ON DELETE RESTRICT
);

CREATE TABLE audit_events (
    id             uuid PRIMARY KEY,
    actor_user_id  uuid REFERENCES app_users(id) ON DELETE SET NULL,
    action         text NOT NULL,
    entity_type    text NOT NULL,
    entity_id      uuid,
    details        jsonb NOT NULL DEFAULT '{}'::jsonb,
    occurred_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX enrollments_student_idx ON enrollments (student_id, status);
CREATE INDEX section_teachers_teacher_idx ON section_teachers (teacher_id, section_id);
CREATE INDEX problem_versions_problem_idx ON problem_versions (problem_id, version_no DESC);
CREATE INDEX test_cases_public_idx ON test_cases (problem_version_id, order_no) WHERE visibility = 'public';
CREATE INDEX exams_status_window_idx ON exams (status, opens_at, closes_at);
CREATE INDEX exam_sections_section_idx ON exam_sections (section_id, exam_id);
CREATE INDEX exam_participants_student_idx ON exam_participants (student_id, exam_id) WHERE status = 'eligible';
CREATE INDEX exam_problems_order_idx ON exam_problems (exam_id, order_no);
CREATE INDEX submissions_participant_problem_idx ON submissions (exam_participant_id, exam_problem_id, submitted_at DESC);
CREATE INDEX submissions_status_idx ON submissions (status, submitted_at);
CREATE INDEX submission_test_results_submission_idx ON submission_test_results (submission_id);
CREATE INDEX audit_events_entity_idx ON audit_events (entity_type, entity_id, occurred_at DESC);

INSERT INTO roles (name) VALUES ('admin'), ('teacher'), ('student')
ON CONFLICT (name) DO NOTHING;

COMMIT;
